package com.ryanjei.orushio.pve.bootstrap;import static org.junit.jupiter.api.Assertions.*;import java.nio.file.*;import org.junit.jupiter.api.*;import org.junit.jupiter.api.io.TempDir;class BootstrapHandoffTest{@TempDir Path temp;@Test void bootstrapUrlを原子的に受け渡し消去する()throws Exception{Path target=temp.resolve("admin-bootstrap.url");BootstrapHandoff handoff=new BootstrapHandoff(target);handoff.publish(8765,"a+b/c=");assertEquals("http://127.0.0.1:8765/auth/bootstrap?token=a%2Bb%2Fc%3D",Files.readString(target));assertFalse(Files.exists(temp.resolve("admin-bootstrap.url.tmp")));handoff.clear();assertFalse(Files.exists(target));}}
